import type { ClassId } from '../character';

/**
 * Talent values the PATCH NOTES state and the client has not shipped yet.
 *
 * ============================================================================
 * WHY THIS LAYER EXISTS AT ALL, AND WHY IT IS NOT AN EDIT TO THE VALUES FILE.
 *
 * `src/data/talents/values/*.json` is GENERATED by matching `{0}` placeholders
 * against each rank's text from `talentsforever.com`. CLAUDE.md names that
 * directory as the one piece of scraped data that is hand-editable -- but read
 * the importer before trusting that: `import_forever_talents.mjs` merges a
 * previous entry ONLY when `entry.values === null`, which is to say only for a
 * SINGLE-RANK talent that has no variable to match. A hand edit to a
 * multi-rank row is silently clobbered by the next `--write`.
 *
 * So a patch note that changes a multi-rank talent's numbers before the client
 * does has nowhere safe to go in the data, and that is exactly the situation
 * this patch arrived in: the notes describe changes that are in NEITHER data
 * source at client build 1.60.1.70291.
 *
 * ----------------------------------------------------------------------------
 * A NOTE OUTRANKS THE CLIENT, WHICH IS THIS PROJECT'S EXISTING RULE RATHER
 * THAN A NEW ONE.
 *
 * `SWIPE_AP_COEFFICIENT` is 3% because the 1.60.1.70170 notes said so while
 * `WoWSimWorksheet.xlsx` says 10%: "the sheet records what the figure was
 * meant to be before the fix landed and the notes record what shipped". The
 * owner has also ruled the other way round once -- where a note and a client
 * TOOLTIP disagreed on Dual Wield Specialization they said "the client tooltip
 * was correct" -- and the two are consistent: a note describes an intent, the
 * client is what players run, and a note about a number the client has not
 * touched yet is a statement about a build that has not landed.
 *
 * THAT IS THE RISK HERE AND IT IS WRITTEN DOWN RATHER THAN HIDDEN. Every entry
 * below is a figure from a note whose build is not in the data, so every one of
 * them is a candidate to be WRONG in the Dual Wield Specialization direction.
 * What makes that survivable is that they are all in one table with the note's
 * own words beside them, so a refresh that brings the real numbers in makes
 * each entry either redundant or demonstrably wrong -- and `patchNoteValues.
 * test.ts` prints the two side by side.
 *
 * ----------------------------------------------------------------------------
 * WHAT MAY NOT GO IN HERE.
 *
 * ONLY A VALUE, never a tree SHAPE. A talent's rank count, row, column and
 * prerequisites live in `src/data/talents/<class>.json` and are read by the
 * decoder, the legality rules and the Talent panel; a note that moves a talent
 * to another row or changes how many points it takes cannot be expressed here
 * and must wait for the client. Several notes in this patch are exactly that
 * and are recorded as blocked rather than approximated -- inventing a tree
 * shape is inventing game data with a build URL that will not decode.
 *
 * AND ONLY WHERE THE NOTE STATES EVERY RANK. "Significantly reduced" is not a
 * number and does not belong here at any confidence.
 * ============================================================================
 */

/** One rank's value: a single number, or a row when the talent states several. */
export type TalentValueRow = number | readonly number[];

export interface PatchNoteValue {
  /** The note's own words, verbatim, so the figure can be re-read against it. */
  readonly note: string;
  /** Which patch note this came from, for the day the client catches up. */
  readonly source: string;
  /** What the generated file says today, so a refresh that changes it is visible. */
  readonly clientSaid: readonly TalentValueRow[];
  /** What the note says. One entry per rank, in rank order. */
  readonly values: readonly TalentValueRow[];
}

/**
 * Keyed by class and then by talent id, which is how every other talent table
 * here is keyed -- a talent id is unique only WITHIN a class, so a flat record
 * could not attribute an entry and every class would be offered every
 * override. `talentsForClass` learned that the hard way.
 */
export const PATCH_NOTE_TALENT_VALUES: Readonly<
  Partial<Record<ClassId, Readonly<Record<string, PatchNoteValue>>>>
> = {
  warlock: {
    /*
     * "Shadow Mastery changed to increasing your Shadow spell damage by
     * 2/4/6/8/10% (Was 1/2/3/4/5%)."
     *
     * A STRAIGHT DOUBLING, which is the easiest kind of entry to check and the
     * easiest to be wrong about in the generous direction -- so the client's
     * own row is recorded beside it. Both Warlock presets take this at 5/5, so
     * it is +10% Shadow where it was +5%.
     */
    shadow_mastery: {
      note: 'Shadow Mastery changed to increasing your Shadow spell damage by 2/4/6/8/10% (Was 1/2/3/4/5%).',
      source: 'Warlock class changes, racial/class patch notes',
      clientSaid: [1, 2, 3, 4, 5],
      values: [2, 4, 6, 8, 10],
    },
  },

  paladin: {
    /*
     * "Champion of the Light now increases your spell damage by 10/20/30% of
     * your Intellect (was 20/40/60%)."
     *
     * HALVED. The talent is `statFromStat` -- intellect into spell power --
     * and the Shockadin builds are three quarters Holy, so this is one of the
     * larger single figures in the patch for them.
     */
    champion_of_the_light: {
      note: 'Champion of the Light now increases your spell damage by 10/20/30% of your Intellect (was 20/40/60%).',
      source: 'Paladin class changes, racial/class patch notes',
      clientSaid: [20, 40, 60],
      values: [10, 20, 30],
    },
  },

  priest: {
    /*
     * "Mental Strength moved to Row 2 from Row 4 and changed to increase your
     * intellect by 2/4/6/8/10%."
     *
     * ONLY THE SECOND HALF IS HERE. The ROW MOVE is a tree change and cannot
     * be expressed in this file -- see the header. It is recorded as blocked,
     * and the consequence is real rather than cosmetic: a talent on row 2 is
     * reachable with 5 points in the tree where row 4 needs 15, so the move
     * opens builds that do not decode today. Applying the value without the
     * row is the honest half: the talent a build already takes is worth what
     * the note says, and no build can yet take it anywhere the note moved it.
     */
    mental_strength: {
      note: 'Mental Strength moved to Row 2 from Row 4 and changed to increase your intellect by 2/4/6/8/10%.',
      source: 'Priest class changes, racial/class patch notes',
      clientSaid: [3, 6, 9, 12, 15],
      values: [2, 4, 6, 8, 10],
    },
  },
};

/**
 * The note's value for a rank, or nothing.
 *
 * RANK IS 1-BASED, matching `talentNumber` and the values files. A rank outside
 * the table's own length returns nothing rather than clamping, so an override
 * written for five ranks cannot quietly answer for a sixth the client added.
 */
export function patchNoteValue(
  characterClass: ClassId,
  talentId: string,
  rank: number,
): TalentValueRow | undefined {
  const entry = PATCH_NOTE_TALENT_VALUES[characterClass]?.[talentId];
  if (!entry) return undefined;
  return entry.values[rank - 1];
}
